<script setup>
const {user,send,busy,fa}=useReiki(),section=ref('content'),editing=ref(false),confirmDelete=ref(null)
const tabs={content:'محتوا',categories:'دسته‌ها',types:'نوع محتوا',calendar:'رویدادها',users:'کاربران',purchases:'خریدها',entitlements:'دسترسی‌ها'}
const {data:rows,error,refresh}=await useFetch(()=>'/api/admin/'+section.value,{immediate:!!user.value?.isAdmin,default:()=>[]})
const {data:types}=await useFetch('/api/catalog/types')
const fresh=()=>({id:null,type_id:types.value?.[0]?.id||1,slug:'',title:'',summary:'',body:'',payload:'{}',access_type:'free',price:0,course_id:null,status:'draft',published_at:'',featured:0,title_fa:'',taxonomy:'general',description:'',field_schema:'[]',kind:'event',starts_at:'',note:'',user_id:null,scope:'course',ref_id:null})
const form=reactive(fresh())
const selectedType=computed(()=>types.value?.find(t=>t.id===Number(form.type_id)))
const schema=computed(()=>{try{return JSON.parse(selectedType.value?.field_schema||'[]')}catch{return []}})
const payloadFields=reactive({})
function edit(row){Object.assign(form,fresh(),row||{});for(const k of Object.keys(payloadFields))delete payloadFields[k];try{Object.assign(payloadFields,JSON.parse(form.payload))}catch{};editing.value=true}
function change(s){section.value=s;editing.value=false;confirmDelete.value=null}
async function save(){if(section.value==='content'&&schema.value.length)form.payload=JSON.stringify(payloadFields);if(await send('/api/admin/'+section.value,form)){editing.value=false;await refresh();await refreshNuxtData()}}
async function remove(id){if(await send('/api/admin/'+section.value,{action:'delete',id})){confirmDelete.value=null;await refresh()}}
async function approve(id){if(await send('/api/admin/purchases',{id}))await refresh()}
async function revoke(id){if(await send('/api/admin/entitlements',{id,action:'revoke'}))await refresh()}
</script>
<template><main class="page admin"><div class="page-heading"><small>Reiki_islove</small><h1>مدیریت برنامه</h1></div><div v-if="!user?.isAdmin" class="state"><p>این بخش فقط برای مدیر است. ثبت‌نام عادی دسترسی مدیر ایجاد نمی‌کند.</p><NuxtLink to="/profile" class="btn btn-primary">ورود به حساب</NuxtLink></div><template v-else><p class="disclaimer">ژورنال خصوصی کاربران در این پنل نمایش داده نمی‌شود. مدیریت فایل، سرفصل دوره و گواهی هنوز در این نسخه فعال نیست.</p><div class="rail filters"><button v-for="(label,key) in tabs" :key="key" class="chip" :aria-pressed="section===key" @click="change(key)">{{label}}</button></div><button v-if="!['users','purchases'].includes(section)" class="btn btn-primary" @click="edit(null)">{{section==='entitlements'?'اعطای دسترسی':'افزودن مورد جدید'}}</button><form v-if="editing" class="card section" @submit.prevent="save"><template v-if="section==='content'"><label class="field"><span>نوع محتوا</span><select v-model="form.type_id" class="select"><option v-for="t in types" :key="t.id" :value="t.id">{{t.title_fa}}</option></select></label><label class="field"><span>عنوان</span><input v-model="form.title" required class="input"/></label><label class="field"><span>شناسهٔ یکتا</span><input v-model="form.slug" required class="input input-ltr"/></label><label class="field"><span>خلاصهٔ عمومی (برای کاربران بدون دسترسی هم نمایش داده می‌شود)</span><textarea v-model="form.summary" class="textarea"/></label><label class="field"><span>متن کامل (طبق سطح دسترسی محافظت می‌شود)</span><textarea v-model="form.body" class="textarea"/></label><label v-for="f in schema" :key="f.key" class="field"><span>{{f.label}}</span><textarea v-if="f.type==='textarea'" v-model="payloadFields[f.key]" class="textarea"/><input v-else v-model="payloadFields[f.key]" class="input" :type="f.type==='number'?'number':'text'" :dir="f.dir||'rtl'"/></label><label v-if="!schema.length" class="field"><span>فیلدهای تکمیلی JSON</span><textarea v-model="form.payload" class="textarea" dir="ltr"/></label><label class="field"><span>سطح دسترسی</span><select v-model="form.access_type" class="select"><option value="free">رایگان</option><option value="premium">عضویت ویژه</option><option value="individual">خرید تکی</option><option value="course">دسترسی دوره</option><option value="specific">کاربر مشخص</option></select></label><label v-if="form.access_type==='course'" class="field"><span>شناسهٔ دورهٔ مورد نیاز</span><input v-model.number="form.course_id" class="input" type="number" min="1" required/></label><label class="field"><span>قیمت به تومان</span><input v-model.number="form.price" class="input" type="number" min="0"/></label><label class="field"><span>وضعیت انتشار</span><select v-model="form.status" class="select"><option value="draft">پیش‌نویس</option><option value="published">منتشرشده</option><option value="hidden">مخفی</option></select></label><label class="field"><span>انتشار از تاریخ (اختیاری؛ ISO با منطقهٔ زمانی)</span><input v-model="form.published_at" class="input input-ltr" placeholder="2026-10-01T09:00:00+03:30"/></label><label><input v-model="form.featured" type="checkbox"/> محتوای منتخب</label></template><template v-else-if="['categories','types'].includes(section)"><label class="field"><span>نام فارسی</span><input v-model="form.title_fa" class="input" required/></label><label class="field"><span>شناسهٔ یکتا {{section==='types'?'(انگلیسی)':''}}</span><input v-model="form.slug" class="input input-ltr" required/></label><label v-if="section==='categories'" class="field"><span>گروه دسته، مانند mantra یا meditation</span><input v-model="form.taxonomy" class="input input-ltr"/></label><label v-else class="field"><span>تعریف فیلدهای فرم به صورت JSON (اختیاری)</span><textarea v-model="form.field_schema" class="textarea" dir="ltr"/></label></template><template v-else-if="section==='calendar'"><label class="field"><span>عنوان رویداد</span><input v-model="form.title" class="input" required/></label><label class="field"><span>نوع رویداد دلخواه</span><input v-model="form.kind" class="input" required/></label><label class="field"><span>زمان ISO با منطقهٔ زمانی</span><input v-model="form.starts_at" class="input input-ltr" placeholder="2026-10-01T18:00:00+03:30" required/></label><label class="field"><span>توضیح رویداد</span><textarea v-model="form.note" class="textarea"/></label></template><template v-else-if="section==='entitlements'"><label class="field"><span>شناسهٔ کاربر (از فهرست کاربران)</span><input v-model.number="form.user_id" class="input" type="number" min="1" required/></label><label class="field"><span>نوع دسترسی</span><select v-model="form.scope" class="select"><option value="premium">ویژه، ۳۰ روز</option><option value="course">دوره</option><option value="content">محتوا</option><option value="program">برنامه</option></select></label><label v-if="form.scope!=='premium'" class="field"><span>شناسهٔ مورد</span><input v-model.number="form.ref_id" class="input" type="number" min="1" required/></label></template><div class="row filters"><button class="btn btn-primary" :disabled="busy">ذخیره</button><button type="button" class="btn btn-ghost" @click="editing=false">انصراف</button></div></form><p v-if="error" role="alert">دریافت فهرست ممکن نشد. دسترسی و ارتباط را بررسی کنید.</p><div class="stack section"><article v-for="row in rows" :key="row.id" class="card"><small>شناسه {{fa(row.id)}}</small><h3>{{row.title||row.title_fa||row.name}}</h3><template v-if="section==='users'"><p dir="ltr">{{row.email}}</p></template><template v-else-if="section==='purchases'"><p>{{row.item_kind}} #{{fa(row.item_id)}} · {{fa(row.amount)}} تومان</p><p>{{row.status==='pending'?'در انتظار بررسی':row.status==='paid'?'تأیید شده':row.status}}</p><button v-if="row.status==='pending'&&confirmDelete!==row.id" class="btn btn-gold" @click="confirmDelete=row.id">تأیید دستی خرید</button><div v-if="confirmDelete===row.id"><p>دریافت وجه این درخواست را بررسی کرده‌اید؟ تأیید، دسترسی ایجاد می‌کند.</p><button class="btn btn-primary" :disabled="busy" @click="approve(row.id);confirmDelete=null">تأیید دریافت وجه</button><button class="btn" @click="confirmDelete=null">انصراف</button></div></template><template v-else-if="section==='entitlements'"><p>{{row.scope}} · {{row.ref_id||'عضویت'}} · {{row.revoked_at?'لغو شده':'صادرشده'}}</p><button v-if="!row.revoked_at" class="btn btn-ghost" :disabled="busy" @click="revoke(row.id)">لغو دسترسی</button></template><template v-else><small>{{row.status||row.slug||row.starts_at}}</small><div class="row filters"><button class="btn btn-ghost" @click="edit(row)">ویرایش</button><button v-if="section!=='types'" class="btn btn-ghost" @click="confirmDelete=row.id">حذف</button></div><div v-if="confirmDelete===row.id"><p>حذف دائمی این مورد تأیید می‌شود؟</p><button class="btn btn-primary" :disabled="busy" @click="remove(row.id)">بله، حذف شود</button><button class="btn" @click="confirmDelete=null">انصراف</button></div></template></article></div></template></main></template>
